from course_model import *
c=chapter('js-start','JavaScript · de la prima valoare','Valori, variabile, funcții, condiții și bucle explicate de la zero.','JavaScript - general.pptx, 3–14; pregătire pentru codul proiectului','braces')
def J(id,title,idea,body,cases,quiz,prompt,explain=None,slides='',mode='js',**extra):
 solution='function solve(input) {\n  '+body.replace('\n','\n  ')+'\n}'
 lesson(c,id,title,idea,solution,explain or idea,quiz,js(prompt,solution,cases,mode=mode,**extra),slides)
J('js-return','Prima instrucțiune: return','În exercițiile noastre primești o funcție numită solve. `return` este instrucțiunea care dă rezultatul. Pentru început modifici doar valoarea returnată.','return "Hello";',[(None,'Hello'),(5,'Hello')],q('Ce instrucțiune dă rezultatul funcției?','return','class','doctype'),'Returnează textul Hello, indiferent de intrare.')
J('js-input','Intrarea unei funcții','input este numele parametrului: valoarea primită din test. Nu este un cuvânt magic al limbajului; îl folosim consecvent pentru claritate.','return input;',[(3,3),('Cake','Cake'),(False,False)],q('Ce reprezintă input în funcția noastră?','Valoarea primită','Întotdeauna un câmp HTML','O comandă Node'),'Returnează exact valoarea primită în input.')
J('js-text','Texte între ghilimele','Un șir, numit string, este text. Îl poți scrie între ghilimele simple sau duble. Deschiderea și închiderea trebuie să corespundă.','return "Welcome to Sweet Corner";',[(None,'Welcome to Sweet Corner')],q('Care este un șir?','"Cake"','Cake fără definiție','{Cake}'),'Returnează textul Welcome to Sweet Corner.')
J('js-number','Numere și operații','Numerele se scriu fără ghilimele. + adună, - scade, * înmulțește, / împarte. Parantezele schimbă ordinea calculului.','return input * 2;',[(3,6),(0,0),(-2,-4)],q('Care operator înmulțește?','*','x obligatoriu','#'),'Returnează dublul numărului input.')
J('js-const','Un nume pentru o valoare','const creează o legătură care nu poate fi reasignată. Numele trebuie declarat înainte să îl folosești în această zonă a codului.','const unitPrice = input;\nreturn unitPrice * 3;',[(5,15),(0,0),(2.5,7.5)],q('Ce nume respectă convenția camelCase?','unitPrice','unit-price ca variabilă JS','unit price'),'Calculează prețul a trei bucăți din prețul unitar input. Folosește numele unitPrice în cod.')
J('js-let','O valoare care se schimbă','let permite reasignarea. La o reasignare nu mai scrii let în fața aceluiași nume în același bloc.','let total = input;\ntotal = total + 5;\nreturn total;',[(2,7),(-5,0)],q('Ce folosești dacă vei reasigna variabila?','let','const obligatoriu','href'),'Returnează input plus 5, folosind variabila total.')
J('js-types','Boolean și tipuri','true și false sunt valori booleene, fără ghilimele. "true" este text. typeof arată categoria unei valori, cu particularități precum typeof null care este object.','return typeof input;',[(4,'number'),('4','string'),(True,'boolean')],q('Ce tip are true fără ghilimele?','boolean','string','array'),'Returnează typeof input.')
J('js-convert','Convertește înainte de adunare','Number transformă un text numeric într-un număr. Dacă aduni două texte, + le concatenează. Datele din formulare și query string sunt de obicei texte.','return Number(input[0]) + Number(input[1]);',[(['5','7'],12),(['2.5','1.5'],4),(['-2','2'],0)],q('Cât este "5" + "7" fără conversie?','"57"','12','35'),'Primești două numere scrise ca texte într-un vector. Returnează suma numerică.')
J('js-compare','Comparații și egalitate strictă','=== compară fără conversie implicită. >, <, >= și <= compară ordinea. Rezultatul unei comparații este boolean.','return input === 10;',[(10,True),('10',False),(9,False)],q('Ce operator folosește egalitate strictă?','===','=','== cu același efect în orice caz'),'Returnează true doar dacă input este numărul 10, nu textul "10".')
J('js-if','Alege între două ramuri','if execută blocul dacă expresia este adevărată; else tratează alternativa. return poate încheia funcția direct din ramură.','if (input >= 18) {\n  return "adult";\n}\nreturn "minor";',[(18,'adult'),(17,'minor'),(30,'adult')],q('Ce ramură tratează alternativa unui if?','else','return obligatoriu','case fără switch'),'Pentru o vârstă input returnează adult la cel puțin 18, altfel minor.')
J('js-logic','Condiții combinate','&& cere ca ambele condiții să fie adevărate. || acceptă cel puțin una. ! inversează adevărul. Folosește paranteze când vrei o grupare clară.','return input >= 1 && input <= 10;',[(1,True),(10,True),(11,False),(-1,False)],q('Ce operator cere ambele condiții?','&&','||','!'),'Verifică dacă input este între 1 și 10 inclusiv.')
J('js-function','Parametri și apeluri','O funcție poate avea un nume și parametri proprii. Definirea ei descrie ce face; apelul cu paranteze execută pașii pentru valori concrete.','function doublePrice(price) {\n  return price * 2;\n}\nreturn doublePrice(input);',[(4,8),(2.5,5)],q('Ce execută funcția doublePrice?','Apelul doublePrice(4)','Doar scrierea numelui','Crearea unui fișier CSS'),'Definește doublePrice(price) și returnează rezultatul apelului pentru input.')
J('js-arrow','Funcții săgeată și callback','O arrow function este o altă formă de funcție. Callback înseamnă o funcție transmisă alteia pentru a fi apelată. Cu corp expresie poți omite return; cu acolade trebuie să îl scrii.','const doublePrice = price => price * 2;\nreturn doublePrice(input);',[(7,14),(0,0)],q('Ce lipsește din n => { n * 2; } pentru a returna rezultatul?','return','const obligatoriu în acolade','Un tag script'),'Creează o funcție săgeată doublePrice și dublează input.')
J('js-scope','Blocuri, let și var','let și const au vizibilitate de bloc. var are comportament de funcție și hoisting; nu presupune că se comportă ca let în interiorul acoladelor. Folosim let și const în proiect.','let price = input;\nif (true) {\n  const discount = 2;\n  price = price - discount;\n}\nreturn price;',[(10,8),(3,1)],q('Unde este disponibil discount în exemplu?','În blocul if','Oriunde în toate fișierele','În CSS'),'Returnează input minus 2 folosind un bloc if și o variabilă locală discount.','discount este declarat numai în bloc; price este declarat în funcție și poate fi schimbat acolo.','4–7')
J('js-for','Repetă cu for','O buclă for are inițializare, condiție și actualizare. Verifică limita pentru a nu omite un element sau pentru a nu crea o buclă infinită.','let total = 0;\nfor (let index = 1; index <= input; index++) {\n  total += index;\n}\nreturn total;',[(3,6),(0,0),(5,15)],q('Ce face index++?','Crește index cu 1','Îl dublează','Îl resetează'),'Returnează suma numerelor de la 1 la input, unde input este un întreg nenegativ.')
J('js-for-of','Parcurge valorile unui vector','for...of oferă valorile pe rând. Pentru total pornești de la 0 și aduni fiecare valoare. Un vector gol nu intră în corpul buclei.','let total = 0;\nfor (const price of input) { total += price; }\nreturn total;', [([2,3],5),([],0),([-2,4],2)],q('Ce oferă for...of pentru un vector?','Valorile elementelor','Doar lungimea','Întotdeauna numele fișierelor'),'Returnează suma valorilor din input folosind for...of.')
J('js-while','while, break și continue','while repetă cât timp condiția este adevărată. break iese din buclă; continue trece la următoarea iterație. Trebuie să existe o cale prin care condiția se schimbă.','let count = 0;\nlet remaining = input;\nwhile (remaining > 0) { remaining--; count++; }\nreturn count;',[(3,3),(0,0),(1,1)],q('Ce oprește imediat bucla curentă?','break','continue','const'),'Numără printr-un while de câte scăderi de 1 ai nevoie ca input nenegativ să ajungă la 0.')
J('js-default-rest','Argumente implicite și rest','Un parametru poate avea o valoare implicită. ...values adună argumentele rămase într-un vector. Nu este aceeași folosire ca spread la un apel.','function sum(...values) { return values.reduce((total, value) => total + value, 0); }\nreturn sum(...input);', [([1,2,3],6),([],0)],q('Ce este values în function sum(...values)?','Un vector cu argumentele','Un număr întotdeauna','O clasă CSS'),'Definește sum cu rest parameters și returnează suma vectorului input.','Rest strânge argumentele la definire; spread le desface la apel. reduce va fi explicat în capitolul vectorilor.','13–14')

c=chapter('js-arrays','JavaScript · vectori și obiecte','Toate operațiile de colecții folosite în filtre, sortare și coș.','JavaScript - general.pptx, 15–64','list')
J('array-index','Indici și length','Un Array este o colecție ordonată. Prima poziție are indice 0. length este numărul de poziții, nu indicele ultimului element.','return input[0];',[(['Cake','Tea'],'Cake'),([4,5],4)],q('Care este primul indice?','0','1','-1'),'Returnează primul element din vectorul input, care este negol.','input[0] citește prima valoare. Ultima este input[input.length - 1].','15–17')
J('array-length','Ultimul element','Pentru un vector negol, ultimul indice este length minus 1. Un element lipsă ar produce undefined.','return input[input.length - 1];',[([2,9],9),(['Cake'],'Cake')],q('Care este ultimul indice al unui vector cu 3 elemente?','2','3','1'),'Returnează ultimul element al vectorului negol input.')
J('array-copy','Copiere și referințe','Atribuirea unui vector unei alte variabile nu îl copiază. [...input] creează o copie superficială; obiectele din interior rămân referințe partajate.','const copy = [...input];\ncopy.push("Tea");\nreturn copy;', [(['Cake'],['Cake','Tea']),([],['Tea'])],q('Ce creează o copie superficială?','[...input]','const copy = input','input.length'),'Returnează o copie a vectorului input cu Tea adăugat la final, fără a schimba input.','Folosim push doar pe copie. Testele verifică faptul că intrarea nu a fost modificată.','18–29')
J('array-push-pop','Adaugă și elimină la final','push adaugă la final și returnează noua lungime. pop elimină și returnează ultimul element. Ambele modifică vectorul asupra căruia sunt apelate.','const copy = [...input];\ncopy.pop();\nreturn copy;', [([1,2,3],[1,2]),([1],[]),([],[])],q('Ce returnează pop pentru un vector negol?','Elementul eliminat','Noua lungime','O copie completă'),'Returnează o copie a input fără ultimul element.','Nu modifica vectorul de intrare; fă întâi o copie.','18–22')
J('array-shift','Operații la început','unshift adaugă la început; shift elimină de la început. Ca push și pop, modifică vectorul.','const copy = [...input];\ncopy.unshift("Cake");\nreturn copy;', [(['Tea'],['Cake','Tea']),([],['Cake'])],q('Ce adaugă la începutul vectorului?','unshift','push','pop'),'Returnează o copie cu Cake adăugat la început.','Copia este un vector nou.','18–22')
J('array-splice','Modifică o zonă cu splice','splice(start, deleteCount, ...items) poate elimina și insera elemente. Returnează elementele eliminate, nu întregul vector final.','const copy = [...input];\ncopy.splice(1, 1, "Tea");\nreturn copy;', [(['Cake','Coffee','Milk'],['Cake','Tea','Milk']),(['A','B'],['A','Tea'])],q('Ce reprezintă al doilea argument al lui splice?','Câte elemente elimină','Indicele final exclusiv','Numărul total de rânduri'),'Într-o copie a input (minimum două elemente), înlocuiește al doilea element cu Tea.','Indicele celui de-al doilea element este 1.','21–22')
J('array-slice','Extrage fără să modifici','slice(start, end) returnează o porțiune nouă. start este inclus, end exclus. Parametrii negativi se raportează la sfârșit.','return input.slice(0, 2);',[([1,2,3],[1,2]),([1],[1]),([],[])],q('Este end inclus în slice(start, end)?','Nu','Da, întotdeauna','Numai dacă este 0'),'Returnează primele cel mult două elemente.','slice nu schimbă input.','29')
J('array-join','Unește și concatenează','join produce un șir din elemente, folosind un separator. concat produce un vector nou prin alăturare. Sunt operații cu rezultate de tipuri diferite.','return input.join(", ");',[(['Cake','Tea'],'Cake, Tea'),([],''),(['Cake'],'Cake')],q('Ce tip returnează join?','string','Array întotdeauna','boolean'),'Unește valorile input cu virgulă și spațiu.','Vectorul gol produce un șir gol.','23')
J('array-search','includes și indexOf','includes spune dacă valoarea există. indexOf oferă primul indice sau -1 când valoarea lipsește. Nu confunda indicele 0 cu false.','return input.values.includes(input.target);',[({'values':[1,2],'target':1},True),({'values':[],'target':1},False)],q('Ce returnează indexOf dacă nu găsește valoarea?','-1','0','null obligatoriu'),'Primești values și target. Returnează dacă target se află în values.','include și exclude sunt răspunsuri booleene în această verificare.','24')
J('array-find','Caută după o condiție','find întoarce primul element pentru care callback-ul este adevărat. findIndex întoarce indicele. Pentru lipsă poți transforma undefined în null cu ?? null.','return input.find(product => product.price > 10) ?? null;', [([{'price':5},{'price':12}],{'price':12}),([],None)],q('Ce returnează find?','Primul element care trece condiția','Toate elementele','Doar true sau false'),'Returnează primul obiect cu price > 10 sau null.','Condiția este testată pe fiecare obiect până la prima potrivire.','25–28')
J('array-filter','Păstrează doar valorile potrivite','filter produce un vector nou cu toate elementele care trec condiția. Ordinea elementelor păstrate rămâne aceeași.','return input.filter(price => price >= 10);',[([5,10,12],[10,12]),([],[]),([2],[])],q('Ce returnează filter fără potriviri?','[]','null obligatoriu','Primul element'),'Păstrează prețurile de cel puțin 10.','Predicatul returnează true pentru valorile pe care vrei să le păstrezi.','30–33')
J('array-filter-index','Callback-ul primește și indicele','Callback-ul filter poate primi value, index și vectorul. Poți selecta după poziție, nu doar după valoare.','return input.filter((value, index) => index % 2 === 0);',[([10,20,30],[10,30]),([],[]),([5],[5])],q('Ce primește al doilea parametru al callback-ului?','Indicele','Întotdeauna lungimea','Numele funcției'),'Păstrează elementele de pe indicii pari (0, 2, 4...).','Indicele începe de la 0, iar restul împărțirii la 2 testează paritatea.','31')
J('array-thisarg','thisArg și funcții obișnuite','Unele metode Array primesc un thisArg pentru callback. O funcție obișnuită poate primi acel this; o arrow function păstrează this lexical și nu îl înlocuiește prin acest argument.','const limits = { minimum: input.minimum };\nreturn input.values.filter(function (value) { return value >= this.minimum; }, limits);',[({'minimum':5,'values':[2,5,8]},[5,8]),({'minimum':0,'values':[]},[])],q('Ce funcție folosește thisArg în exemplu?','Callback-ul function obișnuit','O arrow function care ignoră thisArg','Fișierul CSS'),'Filtrează input.values după input.minimum folosind thisArg.','Nu folosi arrow pentru demonstrarea acestui comportament.','32–33')
J('array-map','Transformă fiecare element','map returnează un vector nou cu aceeași lungime. Fiecare element este rezultatul callback-ului. Nu folosi map doar pentru efecte secundare.','return input.map(price => price * 2);',[([2,3],[4,6]),([],[])],q('Ce metodă transformă fiecare element și creează un vector?','map','find','pop'),'Returnează dublul fiecărei valori.','Nu ai nevoie să construiești manual vectorul rezultat.','34–35')
J('array-from','Transformă un iterabil în Array','Array.from poate transforma un șir, o colecție DOM sau un obiect array-like într-un vector. Poate primi și o funcție de transformare.','return Array.from(input, character => character.toUpperCase());',[('cake',['C','A','K','E']),('',[])],q('Ce poate face Array.from?','Creează un Array dintr-un iterabil','Modifică schema SQL','Creează automat o pagină HTML'),'Returnează literele textului input ca vector de majuscule.','Array.from primește iterabilul și opțional un callback.','36–38')
J('array-some','Există cel puțin unul?','some se oprește când găsește un element care trece condiția. Pentru un vector gol returnează false.','return input.some(price => price > 50);',[([10,60],True),([10,20],False),([],False)],q('Ce verifică some?','Existența a cel puțin unui element potrivit','Că toate valorile sunt identice','Lungimea unui șir'),'Returnează dacă există un preț mai mare de 50.','Callback-ul primește valorile pe rând.','39–45')
J('array-every','Toate valorile trec condiția?','every cere ca fiecare element să treacă condiția. Un vector gol returnează true: nu există un contraexemplu în el.','return input.every(price => price >= 0);',[([0,3],True),([-1,2],False),([],True)],q('Ce returnează [].every(...) ?','true','false întotdeauna','SyntaxError'),'Verifică dacă toate valorile sunt nenegative.','Un singur preț negativ este suficient pentru false.','39–45')
J('array-reduce','Un total din mai multe valori','reduce primește acumulatorul și elementul curent. O valoare inițială 0 face suma bine definită și pentru vectorul gol.','return input.reduce((total, price) => total + price, 0);',[([2,3,5],10),([],0)],q('De ce furnizăm valoarea inițială 0?','Pentru un început numeric și cazul gol','Pentru sortare','Pentru a modifica fiecare element'),'Calculează suma prin reduce.','Fără inițializare, reduce pe un vector gol aruncă o eroare.','46–49')
J('array-reduce-right','Acumulare de la dreapta','reduceRight parcurge de la sfârșit la început. Ordinea contează la concatenare și la operații care nu sunt comutative.','return input.reduceRight((text, part) => text + part, "");',[(['A','B','C'],'CBA'),([], '')],q('În ce direcție parcurge reduceRight?','De la dreapta la stânga','Aleator','Întotdeauna de la stânga'),'Concatenează elementele text ale input în ordine inversă prin reduceRight.','Valoarea inițială este un șir gol.','46')
J('array-sort','Sortare numerică','sort fără comparator compară reprezentări textuale. Comparatorul a - b sortează numere crescător. sort modifică vectorul, deci copiem mai întâi.','return [...input].sort((a, b) => a - b);',[([10,2,30],[2,10,30]),([-2,-10],[-10,-2]),([],[])],q('Ce comparator sortează crescător numeric?','(a, b) => a - b','Fără comparator în orice caz','(a, b) => a + b'),'Returnează o copie sortată numeric crescător.','Un rezultat negativ pune a înainte de b.','52–54')
J('array-sort-keys','Sortare după două criterii','Comparatorul poate decide întâi după price și, la egalitate, după name. localeCompare compară șiruri, nu numere.','return [...input].sort((a, b) => a.price - b.price || a.name.localeCompare(b.name, "en"));',[([{'name':'Tea','price':5},{'name':'Cake','price':5},{'name':'Bread','price':2}],[{'name':'Bread','price':2},{'name':'Cake','price':5},{'name':'Tea','price':5}]),([],[])],q('Când folosim al doilea criteriu în exemplu?','Când prețurile sunt egale','Înaintea prețului întotdeauna','Numai când vectorul e gol'),'Sortează crescător după price și apoi name.','Operatorul || folosește comparația numelor când diferența prețurilor este 0.','55–57; produse.js')
J('array-reverse','Inversează fără a schimba intrarea','reverse inversează ordinea și modifică vectorul. Aplică-l unei copii când nu vrei efecte asupra intrării.','return [...input].reverse();',[([1,2,3],[3,2,1]),([],[])],q('reverse modifică vectorul pe care îl primește?','Da','Nu, niciodată','Doar dacă are texte'),'Returnează ordinea inversă pe o copie.','O copie superficială este suficientă aici.','51,56–57')
J('array-foreach','forEach și efecte secundare','forEach apelează callback-ul pentru fiecare element și nu produce vectorul rezultat ca map. Returnarea din callback nu încheie funcția exterioară.','let total = 0;\ninput.forEach(price => { total += price; });\nreturn total;', [([2,3],5),([],0)],q('Ce metodă alegi când vrei direct un vector transformat?','map','forEach ca rezultat direct','pop'),'Calculează suma folosind forEach și o variabilă total.','Returnează total după parcurgere, nu din callback.','58–59')
J('array-chain','Leagă metodele potrivite','Poți înlănțui metode când rezultatul uneia oferă metoda următoare. filter și map returnează Array; join returnează string.','return input.filter(value => value < 8).sort((a, b) => a - b).map(value => value * 2);',[([10,7,2,9],[4,14]),([],[])],q('De ce putem apela map după filter?','filter returnează un Array','filter returnează întotdeauna true','map acceptă numai SQL'),'Păstrează numerele sub 8, sortează-le crescător și dublează-le.','filter produce un vector nou; sort modifică acea copie rezultată, nu input.','60–61')
J('array-matrix','Vectori de vectori','O matrice poate fi reprezentată ca un Array care conține alte Array-uri. input[row][column] citește o valoare. Nu toate colecțiile imbricate au automat rânduri de aceeași lungime.','return input[1][0];',[([[1,2],[3,4]],3),([[0],[9]],9)],q('Ce citește input[1][0]?','Primul element din al doilea rând','Al doilea din primul','Lungimea matricei'),'Pentru o matrice cu minimum două rânduri nevide, returnează primul element din al doilea rând.','Indicii ambelor niveluri încep de la 0.','62')
J('array-flat','Aplatizare cu flat','flat(depth) reduce nivelurile imbricate. Valoarea implicită depth este 1; nu înseamnă automat toate nivelurile.','return input.flat();',[([[1,2],[3]],[1,2,3]),([[],[4]],[4])],q('Care este adâncimea implicită a flat?','1','Infinit','0 întotdeauna'),'Aplatizează un nivel al vectorului input.','Pentru niveluri arbitrare există flat(Infinity), dar acesta nu este exercițiul de aici.','63')
J('array-flatmap','Transformă și aplatizează un nivel','flatMap aplică map și apoi flat cu adâncime 1. Callback-ul poate întoarce un vector pentru fiecare element.','return input.flatMap(value => [value, value * 2]);',[([2,3],[2,4,3,6]),([],[])],q('Câte niveluri aplatizează flatMap?','Unul','Toate obligatoriu','Niciunul'),'Pentru fiecare număr, pune în rezultat numărul și dublul lui.','Callback-ul întoarce o pereche, iar flatMap le unește.','64')
J('object-properties','Obiecte și proprietăți','Un obiect grupează valori cu nume. product.price citește proprietatea price. Pentru un nume dinamic sau cu cratimă poți folosi paranteze pătrate.','return input.name + ": " + input.price;', [({'name':'Cake','price':10},'Cake: 10'),({'name':'Tea','price':4},'Tea: 4')],q('Cum citești price din obiectul product?','product.price','product[price] fără definiție','product::price'),'Primești un produs. Returnează Name: PRICE folosind proprietățile name și price.','Numele proprietăților și variabilelor rămân în engleză.')
J('object-entries','Chei, valori și perechi','Object.keys oferă numele proprietăților; Object.values valorile; Object.entries perechi [key, value]. Aceste metode sunt utile pentru JSON și query string.','return Object.keys(input).sort();',[({'name':'Cake','price':10},['name','price']),({},[])],q('Ce conține Object.entries?','Perechi cheie-valoare','Numai valori','O comandă Express'),'Returnează numele proprietăților input, sortate alfabetic.','Folosim sortarea pentru o ordine clară în rezultat.')

c=chapter('js-text','JavaScript · șiruri, regex, Date și Math','Toate metodele de text și date din prezentare.','JavaScript - general.pptx, 65–103','text')
J('string-trim','Curăță spațiile de la capete','trim nu elimină spațiile din interior. Șirurile sunt imuabile: metoda returnează un șir nou.','return input.trim();',[('  Cake  ','Cake'),(' Cake tea ','Cake tea'),('','')],q('Ce elimină trim?','Spațiile de la capete','Toate spațiile din interior','Toate literele mari'),'Returnează input fără spații la capete.','Nu trebuie să modifici caracterele dintre cuvinte.','65–68,80–81')
J('string-case','Compară texte normalizate','toLowerCase și toUpperCase schimbă registrul literelor. Filtrele din proiect curăță spațiile și normalizează registrul înainte de comparație.','return input.trim().toLowerCase();',[('  CAKE ','cake'),('Tea','tea')],q('Ce produce toLowerCase?','Un șir nou cu litere mici','O modificare directă a șirului original','Un vector de litere'),'Normalizează input prin trim și litere mici.','Lanțul se citește de la stânga la dreapta.','74')
J('string-template','Template literals','Textele dintre backticks pot include expresii în ${...} și pot ocupa mai multe linii. Ghilimelele obișnuite nu interpretează această sintaxă.','return `${input.name}: ${input.price} EUR`;', [({'name':'Cake','price':10},'Cake: 10 EUR'),({'name':'Tea','price':4},'Tea: 4 EUR')],q('Ce delimitează un template literal?','Backticks','Acolade fără ghilimele','Paranteze pătrate'),'Formatează un produs ca Name: PRICE EUR.','Folosește numele proprietăților în expresiile ${...}.','68–71')
J('string-search','includes, startsWith și endsWith','includes caută oriunde; startsWith la început; endsWith la sfârșit. Metodele sunt sensibile la litere mari și mici.','return input.toLowerCase().startsWith("cake");',[('Cake box',True),('Fruit cake',False),('cake',True)],q('Ce metodă verifică începutul?','startsWith','endsWith','split'),'Returnează dacă input începe cu cake, ignorând registrul.','Normalizează textul înainte de verificare.','72')
J('string-index','Poziția unui subșir','indexOf returnează un indice sau -1. lastIndexOf caută ultima apariție. Un rezultat 0 înseamnă potrivire la început, nu lipsă.','return input.indexOf("cake");',[('cake shop',0),('fruit cake',6),('tea',-1)],q('Ce indică indexOf care returnează 0?','Potrivire la început','Nicio potrivire','Eroare'),'Returnează poziția primei apariții a textului cake.','Nu transforma direct indicele într-un boolean.','73')
J('string-slice','Extrage o porțiune de text','slice(start, end) include start și exclude end. substring are reguli diferite pentru valori negative și pentru capete inversate. Evită substr în cod nou.','return input.slice(0, 3);',[('Chocolate','Cho'),('Tea','Tea'),('Hi','Hi')],q('Este capătul end inclus în slice?','Nu','Da','Numai la șiruri'),'Returnează primele cel mult trei caractere ale input.','Nu ai nevoie să completezi dacă textul este mai scurt.','75–76')
J('string-compare','Comparare textuală','localeCompare oferă un număr negativ, zero sau pozitiv, nu neapărat exact -1 sau 1. Pentru rezultatul boolean verifici semnul.','return input[0].localeCompare(input[1], "en") < 0;', [(['Cake','Tea'],True),(['Tea','Cake'],False),(['Cake','Cake'],False)],q('Pe ce te bazezi din rezultatul localeCompare?','Pe semn','Pe valoarea exactă -1 întotdeauna','Pe lungimea șirului rezultat'),'Verifică dacă primul text vine înaintea celui de-al doilea în compararea en.','Cazul egal produce false la condiția < 0.','77–78')
J('string-split','Desparte în fragmente','split transformă textul într-un vector folosind un separator. Pentru coș putem primi un șir de id-uri separate prin virgulă.','return input === "" ? [] : input.split(",");',[('1,2,3',['1','2','3']),('',[])],q('Ce tip returnează split?','Array','number','CSSStyleDeclaration'),'Transformă id-urile separate prin virgulă în vector; pentru șir gol returnează [].','Valorile rămân texte până când le convertești explicit.','79; produse-cos.js')
J('string-pad','Completare la o lungime minimă','padStart și padEnd completează până la o lungime minimă. Dacă șirul este deja suficient de lung, rămâne neschimbat.','return String(input).padStart(3, "0");',[(7,'007'),(25,'025'),(1000,'1000')],q('Ce face padStart(3, "0") pentru "7"?','"007"','"700"','"0007"'),'Formatează input cu minimum trei caractere, completând la început cu 0.','Transformă întâi numărul în text.','80–81')
J('regex-basic','Un model de text','O expresie regulată descrie un format. /.../ delimitează modelul; test produce boolean. ^ și $ cer începutul și sfârșitul întregii intrări.','return /^[A-Z]{2}\\d{3}$/.test(input);',[('AB123',True),('ab123',False),('XAB123',False),('AB1234',False)],q('Ce asigură ^ și $?','Potrivirea întregului șir','Doar litere mari','Conversia la număr'),'Acceptă exact două litere mari ASCII și trei cifre.','[A-Z] descrie intervalul de litere, iar {2} numărul exact de repetări.','82–95')
J('regex-groups','Grupuri și alternative','Parantezele grupează; | oferă alternative; ?: creează un grup necapturant. Ancorează întregul grup pentru a nu lăsa una dintre alternative neancorată.','return /^(?:cake|tea)$/.test(input);',[('cake',True),('tea',True),('teapot',False),('cupcake',False)],q('Ce operator oferă alternative în regex?','|','&','#'),'Acceptă doar textele cake sau tea.','Ancorele sunt în exteriorul grupului.','85–90')
J('regex-quantifiers','Câte repetări sunt permise?','+ înseamnă cel puțin una; * zero sau mai multe; ? zero sau una; {m,n} un interval de repetări. Un model prea permisiv poate accepta date nedorite.','return /^\\d{2,4}$/.test(input);',[('12',True),('1234',True),('1',False),('12345',False),('ab',False)],q('Ce permite {2,4}?','Între 2 și 4 repetări inclusiv','Exact 6','Cel mult una'),'Acceptă între două și patru cifre.','Păstrează și ancorele pentru întregul șir.','91–94')
J('regex-assertions','Condiții fără consum: lookahead','Un lookahead verifică ce urmează fără să consume caractere în rezultat. (?=...) este pozitiv; (?!...) negativ. Sunt concepte de recunoaștere, nu validatoare universale de date.','return /^(?=.*\\d)[A-Za-z\\d]{3,}$/.test(input);',[('ab2',True),('abc',False),('a1',False),('12a',True)],q('Ce face un lookahead pozitiv?','Verifică o condiție în continuare fără a consuma','Șterge următorul caracter','Sortează literele'),'Acceptă cel puțin trei caractere ASCII alfanumerice și cel puțin o cifră.','Lookahead-ul cere o cifră; clasa de după el controlează întregul conținut.','96–98')
J('date-utc','Componentele unei date','Date reprezintă un moment. Z într-un șir ISO indică UTC. Metodele getUTC... evită diferențele de fus orar pentru acest exercițiu. Lunile încep de la 0.','const date = new Date(input);\nreturn [date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()];',[('2026-10-21T12:00:00Z',[2026,10,21]),('2027-01-01T00:00:00Z',[2027,1,1])],q('Ce valoare are ianuarie în getUTCMonth?','0','1','12'),'Returnează [an, lună de la 1, zi] în UTC.','Nu folosi getMonth dacă vrei explicit componente UTC.','99–101')
J('date-time','Timestamp și intervale','getTime returnează milisecunde de la epoca Unix. Diferența dintre două timestamp-uri este în milisecunde, nu secunde.','return (new Date(input.end).getTime() - new Date(input.start).getTime()) / 1000;', [({'start':'2026-01-01T00:00:00Z','end':'2026-01-01T00:01:00Z'},60)],q('În ce unitate este getTime?','Milisecunde','Secunde','Zile'),'Returnează durata în secunde dintre input.start și input.end.','Împarte diferența la 1000.','99–101; cookies.js')
J('math-round','floor, ceil și round','floor rotunjește spre minus infinit; ceil spre plus infinit; round la cel mai apropiat întreg conform regulilor JavaScript. floor(-1.2) este -2.','return [Math.floor(input), Math.ceil(input), Math.round(input)];',[(2.3,[2,3,2]),(-1.2,[-2,-1,-1])],q('Ce returnează Math.floor(-1.2)?','-2','-1','0'),'Returnează cele trei rotunjiri în ordinea floor, ceil, round.','Numerele negative arată diferența dintre floor și eliminarea zecimalelor.','102')
J('math-minmax','Limite și numere aleatorii','Math.min și Math.max aleg extremele. Math.random produce o valoare în [0,1); nu include 1. Transformarea într-un interval cere scalare și deplasare.','return Math.max(0, Math.min(100, input));', [(-5,0),(30,30),(150,100)],q('Este 1 inclus în rezultatul Math.random?','Nu','Da întotdeauna','Numai duminica'),'Limitează input la intervalul 0..100.','Aplică mai întâi limita superioară și apoi cea inferioară.','102')
